// Evidence capture only. No service implementation, dispatch, DB, or model calls.
import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, realpathSync, writeFileSync } from 'node:fs';
import { resolve, join, relative, isAbsolute } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const root = fileURLToPath(new URL('..', import.meta.url));
const evidenceDirectory = 'docs/ai-review/evidence';
const pluginRoot = 'C:/Codex-AI-Operations/Codex-Team-Router/plugins/codex-team-router';
const runnerPath = 'scripts/team-service-baseline.mjs';
export const repositorySources = [runnerPath, 'scripts/team-service-baseline.test.mjs',
  'scripts/team-service-workflow.mjs', 'scripts/team-service-workflow.test.mjs',
  'scripts/team-routing-contract-audit.mjs', 'scripts/team-routing-contract-audit.test.mjs',
  'scripts/docs-graph-check.mjs', 'scripts/docs-graph-check.test.mjs'];
export const manifestSources = ['department-00-all-teams-room', 'department-01-product-mobile',
  'department-02-data-backend', 'department-03-server-operations', 'department-04-quality-review',
  'department-05-knowledge-orchestration', 'master-01-human-decisions', 'master-02-orchestration',
  'master-03-deputy-context', 'master-04-development-staging', 'master-05-production-recovery']
  .map((name) => `docs/team/chats/${name}.md`);
export const externalSources = ['scripts/team_router.py', 'tests/test_team_router.py'];
export const commands = [
  { id: 'NODE-42', executable: process.execPath, args: ['--test', '--test-reporter=tap',
    'scripts/team-service-workflow.test.mjs', 'scripts/team-routing-contract-audit.test.mjs',
    'scripts/docs-graph-check.test.mjs'] },
  { id: 'ROUTER-38', executable: 'python', args: ['-B', '-m', 'unittest', 'discover', '-s',
    `${pluginRoot}/tests`, '-p', 'test_*.py'] },
  { id: 'COVERAGE-44', executable: process.execPath, args: ['scripts/team-routing-contract-audit.mjs'] },
];
export const sha256 = (bytes) => createHash('sha256').update(bytes).digest('hex');
const same = (left, right) => JSON.stringify(left) === JSON.stringify(right);
function requireCondition(value, code) { if (!value) throw new Error(code); }
function run(executable, args) {
  const result = spawnSync(executable, args, { cwd: root, encoding: 'utf8', shell: false,
    windowsHide: true, timeout: 120000, maxBuffer: 4 * 1024 * 1024 });
  return { executable, args, exitCode: result.status, error: result.error?.code ?? null,
    stdout: result.stdout ?? '', stderr: result.stderr ?? '' };
}
function git(args, raw = false) {
  const result = spawnSync('git', args, { cwd: root, encoding: raw ? undefined : 'utf8',
    shell: false, windowsHide: true, timeout: 15000, maxBuffer: 16 * 1024 * 1024 });
  requireCondition(result.status === 0, 'GIT_READ_FAILED');
  return raw ? result.stdout : result.stdout.trim();
}
function safeRead(base, path) {
  const canonicalBase = realpathSync(base);
  const absolute = realpathSync(join(base, path));
  const part = relative(canonicalBase, absolute);
  requireCondition(part !== '..' && !part.startsWith('..\\') && !part.startsWith('../') && !isAbsolute(part), 'SOURCE_PATH_ESCAPE');
  return readFileSync(absolute);
}
export function deriveResult(id, result) {
  const output = `${result.stdout}\n${result.stderr}`;
  if (result.error || result.exitCode === null) return { status: 'RUN_FAILED' };
  if (id === 'NODE-42') {
    const count = (key) => Number(output.match(new RegExp(`^# ${key} (\\d+)$`, 'm'))?.[1] ?? NaN);
    const tests = count('tests'), passed = count('pass'), failed = count('fail'), skipped = count('skipped');
    return { status: result.exitCode === 0 && tests === 42 && passed === 42 && failed === 0 && skipped === 0
      ? 'EXPECTED_BASELINE_REPRODUCED' : 'BASELINE_CHANGED_OR_FAILED', tests, passed, failed, skipped };
  }
  if (id === 'ROUTER-38') {
    const tests = Number(output.match(/Ran (\d+) tests? in /)?.[1] ?? NaN);
    return { status: result.exitCode === 0 && tests === 38 && /^OK\s*$/m.test(output)
      ? 'EXPECTED_BASELINE_REPRODUCED' : 'BASELINE_CHANGED_OR_FAILED', tests };
  }
  requireCondition(id === 'COVERAGE-44', 'UNKNOWN_CHECK');
  let parsed;
  try { parsed = JSON.parse(result.stdout); } catch { return { status: 'INVALID_COVERAGE_OUTPUT' }; }
  const counts = {};
  if (Array.isArray(parsed.findings)) for (const finding of parsed.findings) counts[finding.code] = (counts[finding.code] ?? 0) + 1;
  return { status: result.exitCode === 1 && parsed.status === 'REQUIREMENTS_NOT_MET'
    && parsed.serviceReady === false && parsed.messageSent === false && parsed.findings?.length === 44
    ? 'KNOWN_REQUIREMENT_GAPS_REPRODUCED' : 'BASELINE_CHANGED_OR_FAILED',
  auditStatus: parsed.status, serviceReady: parsed.serviceReady, messageSent: parsed.messageSent,
  findingCount: parsed.findings?.length ?? null, counts };
}
function captureSources(targetCommit) {
  const manifests = readdirSync(join(root, 'docs/team/chats')).filter((name) => name.endsWith('.md')).sort();
  requireCondition(same(manifests.map((name) => `docs/team/chats/${name}`), manifestSources), 'MANIFEST_SET_CHANGED');
  requireCondition(same(readdirSync(join(pluginRoot, 'tests')).filter((name) => /^test_.*\.py$/.test(name)).sort(), ['test_team_router.py']), 'EXTERNAL_TEST_SET_CHANGED');
  return [
    ...[...repositorySources, ...manifests.map((name) => `docs/team/chats/${name}`)].map((path) => {
      const bytes = safeRead(root, path);
      const commitBytes = git(['show', `${targetCommit}:${path}`], true);
      requireCondition(bytes.equals(commitBytes), `UNCOMMITTED_SOURCE:${path}`);
      return { scope: 'repository', path, sha256: sha256(bytes), text: bytes.toString('utf8') };
    }),
    ...externalSources.map((path) => {
      const bytes = safeRead(pluginRoot, path);
      return { scope: 'external-plugin', path, sha256: sha256(bytes), text: bytes.toString('utf8') };
    }),
  ];
}
export function validateReport(report) {
  requireCondition(report.schemaVersion === 1 && /^[0-9a-f]{40}$/.test(report.targetCommit), 'REPORT_SCHEMA');
  requireCondition(report.serviceReady === false && report.implementationAuthorized === false, 'UNSUPPORTED_READINESS_CLAIM');
  requireCondition(report.historicalFullVerify?.status === 'HISTORICAL_UNPINNED_NOT_REPRODUCED', 'HISTORICAL_CLAIM_PROMOTED');
  requireCondition(Array.isArray(report.sources) && report.sources.length === repositorySources.length + 11 + 2, 'SOURCE_SET');
  requireCondition(new Set(report.sources.map((source) => `${source.scope}:${source.path}`)).size === report.sources.length, 'DUPLICATE_SOURCE');
  const fixedSources = new Set([...repositorySources, ...manifestSources].map((path) => `repository:${path}`).concat(
    externalSources.map((path) => `external-plugin:${path}`)));
  const actualSources = new Set(report.sources.map((source) => `${source.scope}:${source.path}`));
  requireCondition([...fixedSources].every((key) => actualSources.has(key)), 'SOURCE_SET');
  for (const source of report.sources) {
    requireCondition(typeof source.text === 'string' && sha256(source.text) === source.sha256, 'SOURCE_HASH_MISMATCH');
    requireCondition(source.scope === 'repository' || source.scope === 'external-plugin', 'SOURCE_SCOPE');
    requireCondition(!source.path.includes('..') && !isAbsolute(source.path), 'SOURCE_PATH_ESCAPE');
  }
  requireCondition(report.results.length === commands.length, 'CHECK_SET');
  for (const [index, result] of report.results.entries()) {
    const command = commands[index];
    requireCondition(result.id === command.id && same(result.args, command.args), 'COMMAND_MISMATCH');
    requireCondition(result.executable === command.executable, 'EXECUTABLE_MISMATCH');
    requireCondition(result.stdoutSha256 === sha256(result.stdout) && result.stderrSha256 === sha256(result.stderr), 'OUTPUT_HASH_MISMATCH');
    requireCondition(same(result.derived, deriveResult(result.id, result)), 'DERIVED_RESULT_MISMATCH');
  }
  return true;
}
function capture() {
  const targetCommit = git(['rev-parse', 'HEAD']);
  const sources = captureSources(targetCommit);
  const results = commands.map((command) => {
    const result = { id: command.id, ...run(command.executable, command.args) };
    return { ...result, stdoutSha256: sha256(result.stdout), stderrSha256: sha256(result.stderr), derived: deriveResult(command.id, result) };
  });
  requireCondition(git(['rev-parse', 'HEAD']) === targetCommit, 'HEAD_CHANGED_DURING_CAPTURE');
  requireCondition(same(sources, captureSources(targetCommit)), 'SOURCE_CHANGED_DURING_CAPTURE');
  const report = { schemaVersion: 1, capturedAt: new Date().toISOString(), targetCommit,
    nodeVersion: process.version, platform: process.platform, pythonVersion: run('python', ['--version']).stdout.trim(),
    serviceReady: false, implementationAuthorized: false, sources, results,
    historicalFullVerify: { status: 'HISTORICAL_UNPINNED_NOT_REPRODUCED', reportedPassedStages: 4,
      reportedTotalStages: 6, command: ['corepack', 'pnpm', 'verify'],
      source: 'docs/ai-review/evidence/TEAM-SERVICE-CODEX-TEST-001.final.md',
      limitation: 'Historical runner/dependency hashes and mutable development DB state were not captured. No retroactive SHA or commit reproducibility claim.' } };
  validateReport(report);
  return report;
}
function reportPath(name) {
  requireCondition(/^TEAM-SERVICE-BASELINE-[A-Z0-9-]+\.json$/.test(name), 'INVALID_REPORT_NAME');
  return join(root, evidenceDirectory, name);
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    const [mode, name, extra] = process.argv.slice(2);
    requireCondition(!extra && ['--capture', '--verify'].includes(mode), 'USAGE: --capture|--verify TEAM-SERVICE-BASELINE-ID.json');
    const path = reportPath(name);
    if (mode === '--capture') {
      const report = capture();
      writeFileSync(path, `${JSON.stringify(report, null, 2)}\n`, { encoding: 'utf8', flag: 'wx' });
      console.log(JSON.stringify({ status: 'BASELINE_CAPTURED_NOT_SERVICE_PASS', targetCommit: report.targetCommit,
        report: relative(root, path), results: report.results.map(({ id, derived }) => ({ id, ...derived })) }));
    } else {
      const bytes = readFileSync(path);
      const report = JSON.parse(bytes);
      validateReport(report);
      requireCondition(bytes.equals(git(['show', `HEAD:${evidenceDirectory}/${name}`], true)), 'EVIDENCE_NOT_COMMITTED_OR_CHANGED');
      requireCondition(git(['merge-base', report.targetCommit, 'HEAD']) === report.targetCommit, 'TARGET_NOT_ANCESTOR');
      for (const source of report.sources.filter((source) => source.scope === 'repository')) {
        requireCondition(sha256(git(['show', `${report.targetCommit}:${source.path}`], true)) === source.sha256, 'COMMIT_SOURCE_MISMATCH');
      }
      console.log(JSON.stringify({ status: 'COMMITTED_EVIDENCE_INTEGRITY_VERIFIED', targetCommit: report.targetCommit,
        reportSha256: sha256(bytes), serviceReady: false, testsRerun: false }));
    }
  } catch (error) {
    console.error(JSON.stringify({ status: 'BASELINE_EVIDENCE_REJECTED', reason: error.message }));
    process.exitCode = 1;
  }
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { deriveResult, sha256, validateReport, repositorySources, manifestSources, externalSources, commands } from './team-service-baseline.mjs';

function fixture() {
  return { schemaVersion: 1, targetCommit: 'a'.repeat(40), serviceReady: false, implementationAuthorized: false,
    historicalFullVerify: { status: 'HISTORICAL_UNPINNED_NOT_REPRODUCED' },
    sources: [...repositorySources, ...manifestSources].map((path) => ({ scope: 'repository', path, text: '', sha256: sha256('') }))
      .concat(externalSources.map((path) => ({ scope: 'external-plugin', path, text: '', sha256: sha256('') }))),
    results: commands.map((command) => {
      const result = { ...command, exitCode: null, error: 'ETIMEDOUT', stdout: '', stderr: '' };
      return { ...result, stdoutSha256: sha256(''), stderrSha256: sha256(''), derived: deriveResult(result.id, result) };
    }) };
}

test('BL-07 integrity validation permits an honestly failed run, never promotes service readiness', () => {
  assert.equal(validateReport(fixture()), true);
  const report = fixture(); report.serviceReady = true;
  assert.throws(() => validateReport(report), /UNSUPPORTED_READINESS/);
});

test('BL-08 source content, exact manifest set and duplicate sources are checked', () => {
  let report = fixture(); report.sources[0].text = 'changed';
  assert.throws(() => validateReport(report), /SOURCE_HASH/);
  report = fixture(); report.sources[8].path = 'docs/team/chats/invented.md';
  assert.throws(() => validateReport(report), /SOURCE_SET/);
  report = fixture(); report.sources[1] = report.sources[0];
  assert.throws(() => validateReport(report), /DUPLICATE_SOURCE/);
});

test('BL-09 output hashes, derived verdict and commands cannot be silently changed', () => {
  let report = fixture(); report.results[0].stdout = 'PASS';
  assert.throws(() => validateReport(report), /OUTPUT_HASH/);
  report = fixture(); report.results[0].derived.status = 'PASS';
  assert.throws(() => validateReport(report), /DERIVED_RESULT/);
  report = fixture(); report.results[0].args = ['--version'];
  assert.throws(() => validateReport(report), /COMMAND_MISMATCH/);
});

test('BL-10 historical verification cannot be promoted to a reproduced result', () => {
  const report = fixture(); report.historicalFullVerify.status = 'PASS';
  assert.throws(() => validateReport(report), /HISTORICAL_CLAIM/);
});

test('BL-01 42 passing TAP tests are derived from output, not a manual PASS', () => {
  const output = { exitCode: 0, stdout: '# tests 42\n# pass 42\n# fail 0\n# skipped 0\n', stderr: '', error: null };
  assert.equal(deriveResult('NODE-42', output).status, 'EXPECTED_BASELINE_REPRODUCED');
  assert.equal(deriveResult('NODE-42', { ...output, stdout: 'PASS' }).status, 'BASELINE_CHANGED_OR_FAILED');
});
test('BL-02 a skipped case or nonzero exit is not the 42/42 baseline', () => {
  const output = { exitCode: 0, stdout: '# tests 42\n# pass 41\n# fail 0\n# skipped 1\n', stderr: '', error: null };
  assert.equal(deriveResult('NODE-42', output).status, 'BASELINE_CHANGED_OR_FAILED');
  assert.equal(deriveResult('NODE-42', { ...output, error: 'ETIMEDOUT' }).status, 'RUN_FAILED');
});
test('BL-03 Python test count requires exit zero and actual OK', () => {
  const output = { exitCode: 0, stdout: '', stderr: 'Ran 38 tests in 0.8s\n\nOK\n', error: null };
  assert.equal(deriveResult('ROUTER-38', output).status, 'EXPECTED_BASELINE_REPRODUCED');
  assert.equal(deriveResult('ROUTER-38', { ...output, exitCode: 1 }).status, 'BASELINE_CHANGED_OR_FAILED');
});
test('BL-04 expected coverage exit 1 remains requirements not met', () => {
  const data = { status: 'REQUIREMENTS_NOT_MET', serviceReady: false, messageSent: false,
    findings: Array.from({ length: 44 }, () => ({ code: 'MISSING' })) };
  const output = { exitCode: 1, stdout: JSON.stringify(data), stderr: '', error: null };
  const derived = deriveResult('COVERAGE-44', output);
  assert.equal(derived.status, 'KNOWN_REQUIREMENT_GAPS_REPRODUCED');
  assert.equal(derived.serviceReady, false);
  assert.equal(derived.findingCount, 44);
  assert.equal(deriveResult('COVERAGE-44', { ...output, exitCode: 0 }).status, 'BASELINE_CHANGED_OR_FAILED');
});
test('BL-05 invalid coverage output and null exit cannot become PASS', () => {
  assert.equal(deriveResult('COVERAGE-44', { exitCode: 1, stdout: 'PASS', stderr: '', error: null }).status, 'INVALID_COVERAGE_OUTPUT');
  assert.equal(deriveResult('COVERAGE-44', { exitCode: null, stdout: '', stderr: '', error: null }).status, 'RUN_FAILED');
});
test('BL-06 source hash includes exact bytes, including line endings', () => {
  assert.notEqual(sha256('a\n'), sha256('a\r\n'));
});

import { createHash } from 'node:crypto';
import { roles, teams } from './team-routing-contract-audit.mjs';

// A deterministic foreground workflow reducer, not a transport or approval engine.
// The adapter must validate the sealed router contract and real receipts. No IDs
// for provider threads, raw conversations, or credentials belong in this state.
const hash = (value) => createHash('sha256').update(JSON.stringify(value)).digest('hex');
const idPattern = /^[A-Z][A-Z0-9_-]{0,100}$/;
const evidencePattern = /^(TASK|ARTIFACT|RECEIPT):[A-Za-z0-9_.:/#-]{1,240}$/;
function requireValue(condition, code) {
  if (!condition) throw new Error(code);
}

export function createServiceWorkflow({ taskId, correlationId, team, taskPointer }) {
  requireValue(idPattern.test(taskId ?? '') && idPattern.test(correlationId ?? ''), 'INVALID_TASK_ID');
  requireValue(teams.includes(team), 'INVALID_TEAM');
  requireValue(typeof taskPointer === 'string' && evidencePattern.test(taskPointer), 'INVALID_TASK_POINTER');
  // The situation room is a status consumer, not a mandatory dispatch hop.
  const path = [roles.human, roles.master, roles.deputy, team, roles.deputy, roles.master, roles.human];
  const kinds = ['REQUEST', 'TASK_DISPATCH', 'TASK_DISPATCH', 'TASK_RESULT', 'AGGREGATE_RESULT', 'AGGREGATE_RESULT'];
  return {
    schemaVersion: 1, taskId, correlationId, taskPointer, team,
    revision: 0, status: 'READY', leg: 0, activeDeliveryToken: null,
    legs: kinds.map((kind, index) => ({ source: path[index], target: path[index + 1], kind })),
    seen: {}, receipts: [], resultPointer: null, blocker: null,
  };
}

export function nextServiceAction(state, actor) {
  if (['COMPLETED', 'STOPPED', 'REJECTED'].includes(state.status)) return { type: 'TERMINAL', status: state.status };
  if (state.status === 'BLOCKED') {
    if (actor !== state.blocker.source) return { type: 'WAIT_FOR_ACTOR', logicalActor: state.blocker.source };
    return { type: 'REPORT_BLOCKER', ...state.blocker, requiresRouterValidation: true };
  }
  const leg = state.legs[state.leg];
  if (state.status !== 'READY') return { type: 'WAIT_FOR_RECEIPT', deliveryToken: state.activeDeliveryToken };
  if (actor !== leg.source) return { type: 'WAIT_FOR_ACTOR', logicalActor: leg.source };
  return {
    type: 'PREPARE_ROUTE', ...leg, taskId: state.taskId, correlationId: state.correlationId,
    payload: { task_pointer: state.taskPointer, result_pointer: state.resultPointer, workflow_leg: state.leg },
    // Only direction, never execution permission. prepare-dispatch still enforces
    // caller endpoint, mission, activation, kind, scope, lock and dedupe.
    childRoutesNeeded: state.leg < state.legs.length - 1,
    requiresRouterValidation: true,
  };
}

export function applyServiceEvent(state, event, { verifyReceipt } = {}) {
  requireValue(event && idPattern.test(event.eventId ?? ''), 'INVALID_EVENT_ID');
  const fingerprint = hash(event);
  if (Object.hasOwn(state.seen, event.eventId)) {
    requireValue(state.seen[event.eventId] === fingerprint, 'EVENT_ID_CONFLICT');
    return state;
  }
  requireValue(event.expectedRevision === state.revision, 'REVISION_CONFLICT');
  requireValue(event.taskId === state.taskId && event.correlationId === state.correlationId, 'TASK_SCOPE_MISMATCH');
  requireValue(!['COMPLETED', 'STOPPED', 'REJECTED'].includes(state.status), 'TERMINAL_WORKFLOW');
  requireValue(state.receipts.length < 100, 'EVENT_LIMIT_REQUIRES_CHECKPOINT');
  requireValue(typeof event.evidencePointer === 'string' && evidencePattern.test(event.evidencePointer), 'EVIDENCE_REQUIRED');
  const leg = state.legs[state.leg];
  requireValue(typeof verifyReceipt === 'function'
    && verifyReceipt({ state, event, leg }) === true, 'RECEIPT_NOT_VERIFIED');
  const next = structuredClone(state);
  switch (event.type) {
    case 'TOOL_ACCEPTED':
      requireValue(state.status === 'READY' && event.actor === leg.source, 'INVALID_SEND_STATE');
      requireValue(typeof event.deliveryToken === 'string' && /^DELIVERY-[A-Za-z0-9-]{1,100}$/.test(event.deliveryToken), 'DELIVERY_TOKEN_REQUIRED');
      requireValue(!state.receipts.some((receipt) => receipt.type === 'TOOL_ACCEPTED'
        && receipt.deliveryToken === event.deliveryToken), 'DELIVERY_TOKEN_REUSED');
      next.activeDeliveryToken = event.deliveryToken;
      next.status = 'SENT_UNCONFIRMED';
      break;
    case 'ACK':
      requireValue(state.status === 'SENT_UNCONFIRMED' && event.actor === leg.target, 'INVALID_ACK_STATE');
      requireValue(event.deliveryToken === state.activeDeliveryToken, 'DELIVERY_TOKEN_MISMATCH');
      next.status = 'ACKNOWLEDGED';
      break;
    case 'LEG_COMPLETED':
      requireValue(state.status === 'ACKNOWLEDGED' && event.actor === leg.target, 'INVALID_RESULT_STATE');
      requireValue(event.deliveryToken === state.activeDeliveryToken, 'DELIVERY_TOKEN_MISMATCH');
      requireValue(typeof event.resultPointer === 'string' && evidencePattern.test(event.resultPointer), 'RESULT_POINTER_REQUIRED');
      next.resultPointer = event.resultPointer;
      next.leg += 1;
      next.activeDeliveryToken = null;
      next.status = next.leg === next.legs.length ? 'COMPLETED' : 'READY';
      break;
    case 'REJECTED':
      requireValue(['SENT_UNCONFIRMED', 'ACKNOWLEDGED'].includes(state.status)
        && event.actor === leg.target && event.deliveryToken === state.activeDeliveryToken, 'INVALID_REJECTION');
      next.status = 'REJECTED';
      break;
    case 'BLOCKED':
      requireValue(state.status !== 'BLOCKED' && [leg.source, leg.target].includes(event.actor), 'INVALID_BLOCKER');
      next.status = 'BLOCKED';
      next.blocker = { source: event.actor, target: roles.human, kind: 'DECISION_POINTER', evidencePointer: event.evidencePointer };
      break;
    case 'HUMAN_STOP':
      // The adapter must verify an actual human decision; a role name is not proof.
      requireValue(event.actor === roles.human, 'HUMAN_DECISION_REQUIRED');
      next.status = 'STOPPED';
      break;
    default:
      throw new Error('UNSUPPORTED_EVENT');
  }
  next.revision += 1;
  next.seen[event.eventId] = fingerprint;
  next.receipts.push({ type: event.type, leg: state.leg, evidencePointer: event.evidencePointer,
    deliveryToken: event.deliveryToken ?? null });
  return next;
}

import assert from 'node:assert/strict';
import test from 'node:test';
import { createServiceWorkflow, nextServiceAction, applyServiceEvent } from './team-service-workflow.mjs';
import { roles, teams } from './team-routing-contract-audit.mjs';

const initial = () => createServiceWorkflow({ taskId: 'TASK-PILOT', correlationId: 'CORR-PILOT', team: teams[1], taskPointer: 'TASK:TASK-PILOT' });
// Synthetic receipts are test-only. Production MUST supply its real verifier.
const fixtureVerifier = { verifyReceipt: () => true };
const eventFor = (s, type, extra = {}) => ({ eventId: `EVENT-${s.revision}`, expectedRevision: s.revision,
  taskId: s.taskId, correlationId: s.correlationId, type, actor: s.legs[s.leg].target,
  evidencePointer: `RECEIPT:TEST-${s.revision}`, deliveryToken: s.activeDeliveryToken, ...extra });
const send = (s) => applyServiceEvent(s, eventFor(s, 'TOOL_ACCEPTED', { actor: s.legs[s.leg].source, deliveryToken: `DELIVERY-${s.leg}` }), fixtureVerifier);
const ack = (s) => applyServiceEvent(s, eventFor(s, 'ACK'), fixtureVerifier);

test('ordinary assignment goes 01 to CEO to service chief to team, never via room', () => {
  const state = initial();
  assert.deepEqual(state.legs.slice(0, 3).map(({ source, target }) => [source, target]),
    [[roles.human, roles.master], [roles.master, roles.deputy], [roles.deputy, teams[1]]]);
  assert.equal(nextServiceAction(state, roles.human).requiresRouterValidation, true);
  assert.equal(nextServiceAction(state, roles.master).type, 'WAIT_FOR_ACTOR');
});

test('tool acceptance is not ACK, and ACK is not task completion', () => {
  const sent = send(initial());
  assert.equal(sent.status, 'SENT_UNCONFIRMED');
  assert.equal(sent.leg, 0);
  assert.throws(() => applyServiceEvent(sent, eventFor(sent, 'LEG_COMPLETED', { resultPointer: 'ARTIFACT:RESULT' }), fixtureVerifier), /INVALID_RESULT_STATE/);
  assert.equal(ack(sent).status, 'ACKNOWLEDGED');
  assert.equal(ack(sent).leg, 0);
});

test('six-leg synthetic roundtrip advances only on verified result at each hop', () => {
  let state = initial();
  for (let i = 0; i < 6; i++) {
    state = ack(send(state));
    state = applyServiceEvent(state, eventFor(state, 'LEG_COMPLETED', { resultPointer: `ARTIFACT:RESULT-${i}` }), fixtureVerifier);
    state = JSON.parse(JSON.stringify(state));
  }
  assert.equal(state.status, 'COMPLETED');
  assert.equal(state.revision, 18);
