def validate_successor_receipt(receipt: dict[str, Any]) -> None:
    required = {
        "logical_chat_id", "mission_id", "handoff_sha256", "expected_generation",
        "predecessor_endpoint_id", "successor_endpoint_id", "linked_successor_count",
        "restore_verified", "restore_receipt_sha256", "study_gate_passed", "study_gate_receipt_sha256",
        "handoff_path", "successor_link_path", "restore_receipt_path", "study_gate_receipt_path",
    }
    if not isinstance(receipt, dict) or set(receipt) != required:
        fail("SUCCESSOR_RECEIPT_SCHEMA", f"receipt fields must equal {sorted(required)}")
    require_id(receipt["logical_chat_id"], "logical_chat_id")
    require_id(receipt["mission_id"], "mission_id")
    if receipt["linked_successor_count"] != 1:
        fail("SUCCESSOR_COUNT", "exactly one successor is required")
    if not receipt["restore_verified"] or not receipt["study_gate_passed"]:
        fail("SUCCESSOR_GATE", "restore and Study Gate receipts are required")
    if not isinstance(receipt["expected_generation"], int) or receipt["expected_generation"] < 0:
        fail("SUCCESSOR_GENERATION", "expected_generation is invalid")
    for field in ("handoff_sha256", "restore_receipt_sha256", "study_gate_receipt_sha256"):
        if not HEX_RE.fullmatch(receipt[field]):
            fail("SUCCESSOR_HASH", field)
    if not all(isinstance(receipt[field], str) and receipt[field] for field in ("predecessor_endpoint_id", "successor_endpoint_id")):
        fail("SUCCESSOR_ENDPOINT", "runtime endpoint IDs are required")
    for field in ("handoff_path", "successor_link_path", "restore_receipt_path", "study_gate_receipt_path"):
        if not isinstance(receipt[field], str) or not Path(receipt[field]).is_absolute():
            fail("SUCCESSOR_EVIDENCE_PATH", f"{field} must be an absolute runtime path")


def verify_mission_relay_evidence(receipt: dict[str, Any]) -> None:
    validate_successor_receipt(receipt)
    raw_paths = [
        Path(receipt["handoff_path"]), Path(receipt["successor_link_path"]),
        Path(receipt["restore_receipt_path"]), Path(receipt["study_gate_receipt_path"]),
    ]
    for raw_path in raw_paths:
        reject_reparse_components(raw_path)
    handoff_path, successor_path, restore_path, study_path = [path.resolve() for path in raw_paths]
    expected_paths = {
        successor_path: Path(str(handoff_path) + ".successor.json"),
        restore_path: Path(str(handoff_path) + ".restore.json"),
        study_path: Path(str(handoff_path) + ".study-gate.json"),
    }
    if any(actual != expected.resolve() for actual, expected in expected_paths.items()):
        fail("SUCCESSOR_EVIDENCE_PATH", "Mission Relay evidence paths must be canonical handoff sidecars")
    for path in (handoff_path, successor_path, restore_path, study_path):
        if not path.is_file():
            fail("SUCCESSOR_EVIDENCE_PATH", f"missing or unsafe Mission Relay evidence: {path}")
    sidecar = Path(str(handoff_path) + ".sha256")
    reject_reparse_components(sidecar)
    if not sidecar.is_file():
        fail("SUCCESSOR_EVIDENCE_PATH", "sealed handoff SHA sidecar is missing")
    handoff_sha = sha256_file(handoff_path)
    sidecar_tokens = sidecar.read_text(encoding="ascii", errors="replace").split()
    if not sidecar_tokens or sidecar_tokens[0] != handoff_sha or receipt["handoff_sha256"] != handoff_sha:
        fail("SUCCESSOR_HANDOFF_MISMATCH", "handoff file, sidecar, and receipt hash must match")
    handoff = load_json(handoff_path)
    successor = load_json(successor_path)
    restore = load_json(restore_path)
    study = load_json(study_path)
    if handoff.get("status") != "HANDOFF_SEALED":
        fail("SUCCESSOR_HANDOFF_MISMATCH", "handoff is not sealed")
    if (handoff.get("sourceSessionId") != receipt["predecessor_endpoint_id"]
            or (handoff.get("mission") or {}).get("missionId") != receipt["mission_id"]):
        fail("MISSION_LINEAGE", "handoff source session or mission does not match")
    if (successor.get("status") not in {"SUCCESSOR_CREATED", "SUCCESSOR_LINKED"}
            or successor.get("handoffSha256") != handoff_sha
            or successor.get("threadId") != receipt["successor_endpoint_id"]):
        fail("SUCCESSOR_LINK_MISMATCH", "successor link does not match sealed handoff")
    if (sha256_file(restore_path) != receipt["restore_receipt_sha256"]
            or restore.get("status") != "RESTORE_VERIFIED" or restore.get("sha256") != handoff_sha):
        fail("SUCCESSOR_RESTORE_MISMATCH", "restore receipt is not verified or hash-bound")
    if (sha256_file(study_path) != receipt["study_gate_receipt_sha256"]
            or study.get("status") != "STUDY_GATE_PASSED"
            or study.get("handoffSha256") != handoff_sha
            or Path(str(study.get("restoreReceiptPath") or "")).resolve() != restore_path
            or int(study.get("qualifyingReviewRounds") or 0) < 3
            or int(study.get("qualifyingCrossReviewRounds") or 0) < 2
            or study.get("failures") not in ([], None)):
        fail("SUCCESSOR_STUDY_MISMATCH", "Study Gate receipt is not passed or hash-bound")


def plan_successor(data_root: Path, project_id: str, receipt: dict[str, Any]) -> dict[str, Any]:
    verify_mission_relay_evidence(receipt)
    key = load_or_create_hmac_key(data_root, project_id)
    return {
        "status": "SUCCESSOR_BINDING_PLANNED",
        "messageSent": False,
        "logicalChatId": receipt["logical_chat_id"],
        "missionId": receipt["mission_id"],
        "expectedGeneration": receipt["expected_generation"],
        "nextGeneration": receipt["expected_generation"] + 1,
        "predecessorEndpointRef": endpoint_hmac(receipt["predecessor_endpoint_id"], key),
        "successorEndpointRef": endpoint_hmac(receipt["successor_endpoint_id"], key),
        "handoffSha256": receipt["handoff_sha256"],
    }


def apply_successor(data_root: Path, project_id: str, policy: dict[str, Any], receipt: dict[str, Any]) -> dict[str, Any]:
    if not policy["dispatchEnabled"] or policy["decisionStatus"] != "ACTIVE_NON_PRODUCTION_DISPATCH":
        fail("SUCCESSOR_ACTIVATION_DISABLED", "implementation-only policy cannot activate an endpoint")
    verify_mission_relay_evidence(receipt)
    key = load_or_create_hmac_key(data_root, project_id)
    chat_id = receipt["logical_chat_id"]
    path = data_root / project_id / "endpoints" / f"{chat_id}.json"
    with exclusive_lock(path.with_suffix(".lock")):
        current = load_json(path) if path.exists() else None
        expected = receipt["expected_generation"]
        if current is None:
            if expected != 0:
                fail("GENERATION_CAS", "initial endpoint generation must start at 0")
        else:
            if current.get("handoff_sha256") == receipt["handoff_sha256"]:
                fail("DUPLICATE_HANDOFF_SUCCESSOR", "one handoff cannot activate a second successor generation")
            if current.get("generation") != expected or current.get("active_endpoint_id") != receipt["predecessor_endpoint_id"]:
                fail("GENERATION_CAS", "predecessor endpoint or generation changed")
            if current.get("mission_id") != receipt["mission_id"] or current.get("logical_chat_id") != chat_id:
                fail("MISSION_LINEAGE", "mission or logical chat changed")
        updated = {
            "logical_chat_id": chat_id,
            "mission_id": receipt["mission_id"],
            "generation": expected + 1,
            "active_endpoint_id": receipt["successor_endpoint_id"],
            "active_endpoint_hmac": endpoint_hmac(receipt["successor_endpoint_id"], key),
            "predecessor_endpoint_hmac": endpoint_hmac(receipt["predecessor_endpoint_id"], key),
            "handoff_sha256": receipt["handoff_sha256"],
            "restore_receipt_sha256": receipt["restore_receipt_sha256"],
            "study_gate_receipt_sha256": receipt["study_gate_receipt_sha256"],
            "state": "ACTIVE_SUCCESSOR",
            "updated_at": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
        }
        atomic_json(path, updated)
    return {"status": "ACTIVE_SUCCESSOR", "logicalChatId": chat_id,
            "generation": updated["generation"], "endpointRef": updated["active_endpoint_hmac"]}


def output(value: Any) -> None:
    print(json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2))


