def main(argv: list[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        if args.command == "validate-policy":
            policy = load_policy(Path(args.project_root).resolve())
            output({"status": "POLICY_VALID", "mode": policy["mode"],
                    "dispatchEnabled": policy["dispatchEnabled"], "humanRelayEnabled": policy["humanRelayEnabled"]})
        elif args.command == "validate-manifests":
            root = Path(args.project_root).resolve()
            policy = load_policy(root)
            manifests = load_manifests(root, policy["expectedChatCount"])
            output({"status": "MANIFESTS_VALID", "chatCount": len(manifests),
                    "edgeCount": sum(len(item["sends_to"]) for item in manifests.values())})
        elif args.command == "simulate":
            output(simulate(args))
        elif args.command == "pilot":
            output(run_pilot(args))
        elif args.command == "append-event":
            policy = load_policy(Path(args.project_root).resolve())
            output(append_event(Path(args.data_root), args.project_id, load_json(Path(args.event_file)), policy))
        elif args.command == "verify-chain":
            count, tail = verify_chain(Path(args.ledger), args.expected_tail_sha256)
            output({"status": "CHAIN_VALID", "entryCount": count, "tailSha256": tail})
        elif args.command == "accept-dedupe":
            output(accept_dedupe(Path(args.data_root), args.project_id, load_json(Path(args.record_file))))
        elif args.command == "plan-successor":
            output(plan_successor(Path(args.data_root), args.project_id, load_json(Path(args.receipt_file))))
        elif args.command == "apply-successor":
            policy = load_policy(Path(args.project_root).resolve())
            output(apply_successor(Path(args.data_root), args.project_id, policy, load_json(Path(args.receipt_file))))
        elif args.command == "bind-initial-endpoint":
            policy = load_policy(Path(args.project_root).resolve())
            output(bind_initial_endpoint(
                Path(args.data_root), args.project_id, policy, load_json(Path(args.binding_file))
            ))
        elif args.command == "bind-canonical-root":
            output(bind_canonical_root(
                Path(args.data_root), args.project_id, Path(args.project_root), args.decision_id
            ))
        elif args.command == "validate-receiver-root":
            output(validate_receiver_root(
                Path(args.data_root), args.project_id, args.canonical_project_root
            ))
        elif args.command == "prepare-dispatch":
            output(prepare_dispatch(args))
        elif args.command == "record-delivery":
            output(record_delivery(args))
        elif args.command == "record-rejection":
            output(record_rejection(args))
        elif args.command == "record-failure":
            output(record_failure(args))
        return 0
    except RouterError as error:
        output({"status": "BLOCKED", "code": error.code, "message": str(error)})
        return 2


if __name__ == "__main__":
    sys.exit(main())
